import pandas as pd


def run(inputs: dict) -> dict:
    target = inputs['target_snapshot'].copy()
    cdc = inputs['cdc_events'].copy()
    watermark = inputs['watermark'].copy()

    # Extract watermark high_ts (single row expected)
    high_ts = watermark['high_ts'].iloc[0]

    # Keep only events strictly after the watermark
    cdc = cdc[cdc['event_ts'] > high_ts]

    # Apply sequentially by (event_ts, event_seq), stable sort to preserve
    # deterministic tie-breaking on equal keys (shouldn't normally tie, but
    # mergesort keeps original relative order as a fallback).
    cdc = cdc.sort_values(['event_ts', 'event_seq'], kind='mergesort')

    # Build initial state from target_snapshot
    state = {}
    for _, row in target.iterrows():
        state[row['user_id']] = {
            'email': row['email'],
            'status': row['status'],
            'status_ts': row['status_ts'],
        }

    seven_days = pd.Timedelta(days=7)

    for _, ev in cdc.iterrows():
        uid = ev['user_id']
        op = ev['op']
        ts = ev['event_ts']
        email = ev['email']

        cur = state.get(uid)

        if op == 'D':
            if cur is None:
                # No prior record: create a deleted record with the event's
                # email (nothing to "preserve" from).
                state[uid] = {
                    'email': email,
                    'status': 'DELETED',
                    'status_ts': ts,
                }
            else:
                # Soft delete: preserve existing email, update status/ts.
                state[uid] = {
                    'email': cur['email'],
                    'status': 'DELETED',
                    'status_ts': ts,
                }
        elif op == 'U':
            if cur is None or cur['status'] == 'ACTIVE':
                # Upsert on new or active user.
                state[uid] = {
                    'email': email,
                    'status': 'ACTIVE',
                    'status_ts': ts,
                }
            elif cur['status'] == 'DELETED':
                # Resurrection only if strictly more than 7 days after
                # the deletion's status_ts; otherwise discard the update.
                if ts > (cur['status_ts'] + seven_days):
                    state[uid] = {
                        'email': email,
                        'status': 'ACTIVE',
                        'status_ts': ts,
                    }
                # else: discard, state unchanged
            # else: unknown status, leave unchanged (defensive, shouldn't occur)

    rows = []
    for uid, info in state.items():
        rows.append({
            'user_id': uid,
            'email': info['email'],
            'status': info['status'],
            'status_ts': info['status_ts'],
        })

    new_snapshot = pd.DataFrame(
        rows, columns=['user_id', 'email', 'status', 'status_ts']
    )

    return {'new_snapshot': new_snapshot}
